-- Seed base fields for existing Sima subscribers; never overwrites definitions.
insert into public.crm_field_definitions(tenant_id,key,label,type,options,priority,question,condition,ask_enabled)
select distinct s.customer_id,f->>'key',f->>'label',f->>'type',coalesce(f->'options','[]'::jsonb),(f->>'priority')::integer,f->>'question',f->>'condition',coalesce((f->>'ask_enabled')::boolean,true)
from public.customer_subscriptions s join public.store_products p on p.id=s.product_id cross join jsonb_array_elements('[{"key":"birthday","label":"روز و ماه تولد","type":"birthday","priority":30,"question":"اگر دوست دارید روز تولدتان برایتان پیام تبریک بفرستیم، روز و ماه تولدتان را می‌گویید؟","condition":"after_purchase"},{"key":"contact_time","label":"زمان ترجیحی تماس","type":"text","priority":60,"question":"چه ساعتی برای ارتباط با شما مناسب‌تر است؟","condition":"always"},{"key":"occupation","label":"شغل یا نوع مشتری","type":"select","options":["مصرف‌کننده","همکار","صاحب کسب‌وکار"],"priority":70,"question":"برای مصرف خودتان تهیه می‌کنید یا برای کسب‌وکارتان؟","condition":"active_lead"},{"key":"secondary_phone","label":"شماره تماس دوم","type":"text","priority":20,"question":"اگر مایلید، شماره تماس دیگری برای هماهنگی ثبت کنیم؟","condition":"after_purchase"},{"key":"province","label":"استان","type":"text","priority":50,"question":"برای بررسی ارسال، در کدام استان هستید؟","condition":"active_lead"},{"key":"address","label":"آدرس ارسال","type":"text","priority":80,"question":"برای ارسال سفارش، آدرس تحویل را می‌فرمایید؟","condition":"after_purchase"},{"key":"email","label":"ایمیل","type":"text","priority":20,"question":"اگر مایلید، ایمیلی برای دریافت اطلاعات ثبت کنیم؟","condition":"after_purchase"},{"key":"account_code","label":"کد حسابداری","type":"text","priority":10,"question":"","condition":"always","ask_enabled":false},{"key":"acquisition_source","label":"روش آشنایی با کسب‌وکار","type":"text","priority":40,"question":"از چه طریقی با ما آشنا شدید؟","condition":"always"}]'::jsonb) f
where p.service_code='crm' and s.starts_at<=now() and s.expires_at>now()
on conflict(tenant_id,key) do nothing;
